// CITS5017 Lecture 2 — Training Deep Neural Networks (Géron ch. 11). Pure data; see tools/dl-arcade/BRIEF-slide-reader.md.
// Sources: Documents/cits5017/lectures/cits5017-lect02-Training-DNNs.pdf (68 slides) and markdown-lecs/lecture-2.md.
// Every slide number below was confirmed against the PDF's "N / 68" footer. Equation and figure slides were rendered
// and read as images; the KaTeX follows the slides' symbols (θ, η, ∇θJ(θ), m, s, β, β₁, β₂, ρ, ε, ⊗, ⊘, t).
// Convention (as in the brief's example): θ is written plain and m / s as \mathbf; the slides typeset all three bold.

export const LECTURE = 2;
export const TITLE = 'Training Deep Neural Networks';
export const SLIDE_COUNT = 68;

export const CONCEPTS = [
  { id: 'init.vanishing', lecture: 2, title: 'Vanishing / exploding gradients', slides: [5, 6], hard: 2,
    summary: 'Gradients get smaller and smaller down to the lower layers (or larger and larger), so the lower layers’ weights are left virtually unchanged.' },
  { id: 'init.glorot', lecture: 2, title: 'Glorot (Xavier) initialization', slides: [7, 8, 9], hard: 3,
    summary: 'Normal with mean 0 and variance 1/fan_avg, or uniform on [−r, r] with r = √(3/fan_avg); Keras’s default is Glorot uniform.' },
  { id: 'init.he', lecture: 2, title: 'He (Kaiming) initialization', slides: [8, 9], hard: 2,
    summary: 'For ReLU and its variants (including ELU, GELU, Swish, Mish): σ² = 2/fan_in; kernel_initializer="he_normal".' },
  { id: 'init.lecun', lecture: 2, title: 'LeCun initialization', slides: [8, 16], hard: 2,
    summary: 'For SELU with a normal distribution: σ² = 1/fan_in.' },
  { id: 'init.which', lecture: 2, title: 'Which initialization goes with which activation (Table 11-1)', slides: [8], hard: 3,
    summary: 'Glorot: None, tanh, sigmoid, softmax; He: ReLU, Leaky ReLU, ELU, GELU, Swish, Mish; LeCun: SELU.' },
  { id: 'act.relu', lecture: 2, title: 'ReLU and dying ReLUs', slides: [10], hard: 1,
    summary: 'ReLU does not saturate for positive values, but some neurons “die” and output only 0 when their input is negative.' },
  { id: 'act.leakyRelu', lecture: 2, title: 'Leaky ReLU (and its α)', slides: [11, 12], hard: 2,
    summary: 'LeakyReLU_α(z) = max(αz, z) with a small α such as 0.01; a larger leak (0.2) tends to perform better; Keras default is 0.3.' },
  { id: 'act.rrelu', lecture: 2, title: 'Randomized leaky ReLU (RReLU)', slides: [13], hard: 2,
    summary: 'α is picked randomly in a range during training and fixed to an average value during testing; no Keras implementation.' },
  { id: 'act.prelu', lecture: 2, title: 'Parametric leaky ReLU (PReLU)', slides: [14], hard: 2,
    summary: 'α is learned during training with the connection weights; strong on large image datasets, risks overfitting small ones.' },
  { id: 'act.elu', lecture: 2, title: 'ELU', slides: [15], hard: 2,
    summary: 'α(exp(z) − 1) for z < 0, z for z ≥ 0: negative values, non-zero gradient for z < 0, smooth everywhere when α = 1.' },
  { id: 'act.selu', lecture: 2, title: 'SELU and the conditions for self-normalisation', slides: [16, 17], hard: 3,
    summary: 'SELU(z) = s·ELU₁.₆₇₃₃(z) with s = 1.0507; preserves mean and variance between layers only under three constraints.' },
  { id: 'act.gelu', lecture: 2, title: 'GELU', slides: [18, 21], hard: 2,
    summary: 'GELU(z) = zΦ(z); neither convex nor monotonic; ≈ zσ(1.702z); more computationally intense.' },
  { id: 'act.swish', lecture: 2, title: 'Swish / SiLU', slides: [19, 21], hard: 2,
    summary: 'SiLU(z) = zσ(z), generalised to Swish_β(z) = zσ(βz); GELU ≈ Swish with β = 1.702; renamed silu from tf-2.16.' },
  { id: 'act.mish', lecture: 2, title: 'Mish', slides: [20, 21], hard: 2,
    summary: 'Mish(z) = z·tanh(softplus(z)); smooth, non-convex, non-monotonic; not supported in Keras.' },
  { id: 'act.which', lecture: 2, title: 'Which activation to use for hidden layers', slides: [22], hard: 2,
    summary: 'ReLU for simple tasks; SiLU (Swish) for complex tasks, Mish for slightly better results, leaky ReLU/PReLU if latency matters, SELU for very deep MLPs.' },
  { id: 'bn.algorithm', lecture: 2, title: 'Batch Normalization: the four equations', slides: [23, 24], hard: 3,
    summary: 'μ_B and σ²_B over the mini-batch, x̂ = (x − μ_B)/√(σ²_B + ε), z = γ ⊗ x̂ + β.' },
  { id: 'bn.params', lecture: 2, title: 'BN parameters: γ, β trainable; moving mean and variance not', slides: [23, 24, 27], hard: 3,
    summary: 'γ and β are trainable scale and shift vectors (one per input feature); the per-layer mean and variance are moving averages used at test time.' },
  { id: 'bn.benefits', lecture: 2, title: 'What BN buys you (Ioffe & Szegedy)', slides: [25], hard: 1,
    summary: 'Reduced vanishing gradients, larger learning rates, acts like a regularizer, removes the need to normalize inputs; runtime penalty per layer.' },
  { id: 'bn.keras', lecture: 2, title: 'BN in Keras and its model.summary()', slides: [26, 27], hard: 3,
    summary: 'BatchNormalization() after Flatten and after each hidden Dense; 271,346 params of which 2,368 are non-trainable.' },
  { id: 'bn.placement', lecture: 2, title: 'BN before vs after the activation', slides: [23, 26, 28], hard: 2,
    summary: 'To put BN before the activation, make the activation a separate layer and set use_bias=False on the preceding Dense.' },
  { id: 'clip.gradient', lecture: 2, title: 'Gradient clipping: clipvalue vs clipnorm', slides: [29], hard: 2,
    summary: 'clipvalue=1.0 clips every component to [−1.0, 1.0]; clipnorm=1.0 retains the gradient vector’s orientation.' },
  { id: 'transfer.reuse', lecture: 2, title: 'Transfer learning: which layers to reuse', slides: [30], hard: 2,
    summary: 'Reuse most layers except the top ones; replace the output layer; the more similar the tasks, the more (lower) layers to reuse.' },
  { id: 'transfer.freeze', lecture: 2, title: 'Freeze, train, unfreeze, recompile', slides: [31], hard: 3,
    summary: 'Freeze the reused layers for the first epochs (trainable = False), then unfreeze and recompile before training again.' },
  { id: 'transfer.result', lecture: 2, title: 'Transfer-learning result on Fashion MNIST (91.85% → 93.85%)', slides: [31, 32], hard: 2,
    summary: 'A 2% accuracy improvement is almost a 25% reduction in error rate; the result came from many trials and transfer learning does not work well with small dense nets.' },
  { id: 'optim.gd', lecture: 2, title: 'Gradient Descent update', slides: [34], hard: 1,
    summary: 'θ ← θ − η∇θJ(θ); it does not care what the earlier gradients were.' },
  { id: 'optim.momentum', lecture: 2, title: 'Momentum optimization', slides: [34, 35], hard: 2,
    summary: 'm ← βm − η∇θJ(θ); θ ← θ + m. The gradient is an acceleration, not a speed; β < 1, usually 0.9.' },
  { id: 'optim.nag', lecture: 2, title: 'Nesterov Accelerated Gradient', slides: [36, 37], hard: 3,
    summary: 'Measures the gradient slightly ahead in the direction of the momentum, at θ + βm; nesterov=True.' },
  { id: 'optim.adagrad', lecture: 2, title: 'AdaGrad', slides: [38, 39, 40], hard: 2,
    summary: 's accumulates squared gradients and scales the step down along steep dimensions; often stops too early, so do not use it for DNNs.' },
  { id: 'optim.rmsprop', lecture: 2, title: 'RMSProp', slides: [41, 42], hard: 2,
    summary: 'Fixes AdaGrad’s slowing down by accumulating only the most recent gradients with decay rate ρ (typically 0.9).' },
  { id: 'optim.adam', lecture: 2, title: 'Adam (adaptive moment estimation)', slides: [43, 44], hard: 3,
    summary: 'Momentum + RMSProp with bias-corrected m̂ and ŝ; β₁ = 0.9, β₂ = 0.999, η = 0.001 often works.' },
  { id: 'optim.adamax', lecture: 2, title: 'AdaMax', slides: [45, 46], hard: 2,
    summary: 'Same as Adam except step 2 becomes s ← max(β₂s, abs(∇θJ(θ))); in general Adam performs better.' },
  { id: 'optim.nadam', lecture: 2, title: 'Nadam', slides: [45, 46], hard: 2,
    summary: 'Adam plus the Nesterov trick; generally outperforms Adam but is sometimes outperformed by RMSProp.' },
  { id: 'optim.adamw', lecture: 2, title: 'AdamW (weight decay)', slides: [45, 46], hard: 2,
    summary: 'Integrates weight decay into Adam: weights are multiplied by a decay factor such as 0.99 at each iteration.' },
  { id: 'optim.summary', lecture: 2, title: 'Optimizer comparison (Table 11-2)', slides: [47], hard: 2,
    summary: 'SGD: speed * quality ***; AdaGrad: *** but * (stops too early); RMSprop/Adam/AdaMax/Nadam/AdamW: *** and ** or ***.' },
  { id: 'sched.why', lecture: 2, title: 'Why schedule the learning rate', slides: [48, 49], hard: 1,
    summary: 'Too high diverges, too low is slow; start high then reduce once progress stalls beats the optimal constant rate.' },
  { id: 'sched.power', lecture: 2, title: 'Power scheduling', slides: [50, 51], hard: 2,
    summary: 'η(t) = η₀/(1 + rt/s)^c with c typically 1: down to η₀/(1 + r) after s steps, η₀/(1 + 2r) after 2s; Keras InverseTimeDecay.' },
  { id: 'sched.exponential', lecture: 2, title: 'Exponential scheduling', slides: [52, 53, 54], hard: 2,
    summary: 'η(t) = η₀ r^{t/s} drops by a factor of r every s steps; Keras ExponentialDecay or a LearningRateScheduler callback (per epoch).' },
  { id: 'sched.piecewise', lecture: 2, title: 'Piecewise constant scheduling', slides: [55, 56], hard: 1,
    summary: 'A constant rate for a number of iterations, then a smaller one; Keras PiecewiseConstantDecay(boundaries, values).' },
  { id: 'sched.performance', lecture: 2, title: 'Performance scheduling (ReduceLROnPlateau)', slides: [57, 58], hard: 2,
    summary: 'Reduce the learning rate by a factor when the validation error stops dropping: factor=0.5, patience=5.' },
  { id: 'sched.onecycle', lecture: 2, title: '1Cycle scheduling', slides: [59], hard: 2,
    summary: 'Grow linearly from η₀ to η₁ by halfway, decrease linearly back to η₀, then drop by several orders of magnitude in the last epochs.' },
  { id: 'reg.l1l2', lecture: 2, title: 'ℓ1 and ℓ2 regularization in Keras', slides: [60, 61], hard: 2,
    summary: 'kernel_regularizer=tf.keras.regularizers.l2(0.01) adds a regularization loss to the final loss at each step; l1(...) and l1_l2(...) also exist.' },
  { id: 'reg.dropout', lecture: 2, title: 'Dropout', slides: [62, 63, 64], hard: 2,
    summary: 'Each neuron (inputs included, outputs excluded) is temporarily dropped with probability p (10–50%) at each training step; nothing is dropped after training.' },
  { id: 'mlp.defaults', lecture: 2, title: 'Default DNN configuration (Tables 11-3 and 11-4)', slides: [65, 66], hard: 2,
    summary: 'He init, ReLU if shallow / Swish if deep, BN if deep, early stopping, NAG or AdamW, performance scheduling or 1cycle; self-normalizing: LeCun + SELU + no normalization.' },
];

